package com.bibliotech.notification.entity;import jakarta.persistence.*;import java.time.*;@Entity public class Notification{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)Long id;Long userId,rentalId;String message,type;LocalDateTime createdAt;public Long getId(){return id;}public Long getUserId(){return userId;}public void setUserId(Long v){userId=v;}public Long getRentalId(){return rentalId;}public void setRentalId(Long v){rentalId=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public String getType(){return type;}public void setType(String v){type=v;}public LocalDateTime getCreatedAt(){return createdAt;}public void setCreatedAt(LocalDateTime v){createdAt=v;}}
